// Synthetic ESM package: default, named and namespace imports of builtins.
import fs from "node:fs";
import { appendFileSync, readFileSync } from "fs";
import * as os from "node:os";

export function log(file, line) {
  appendFileSync(file, `${os.hostname().length > 0 ? "host" : "?"} ${line}\n`);
  return fs.statSync(file).size;
}
export function readBack(file) {
  return readFileSync(file, "utf8");
}
// Exposed so the checks can test live bindings.
export function currentReadFileSync() {
  return readFileSync;
}
export { fs, os };
